PACK = dict(
    slug="local-review-management", num=10, short="Reviews", name="Local Business Review Management",
    buyer="Local service businesses (cleaners, trades, salons, clinics, detailers)",
    price=dict(lite=29, pro=39),
    cfg=dict(business_name="YOUR BUSINESS", business_phone="(555) 000-0000", review_link="https://g.page/r/YOUR-REVIEW-LINK"),
    sheets={},
    flows=[
        dict(id="customer", kind="intake", title="Log A Completed Job", lite=True, hook="review-customer",
             rt=dict(
                 sheet="Customers", id_col="customer_id", id_prefix="C", dedupe=["email", "job_date"],
                 fields=[
                     dict(key="name", required=True, sample="Pat Rivera"),
                     dict(key="email", type="email", required=True, sample="pat@example.test"),
                     dict(key="service", max_length=80, sample="House cleaning"),
                     dict(key="job_date", type="date", default_today=True, sample="2026-10-10"),
                 ],
                 extra_cols=[dict(key="status", value="active"), dict(key="reviewed", value=""), dict(key="opted_out", value="")])),
        dict(id="requests", kind="sequence", title="Review Requests", lite=True, cron="0 11 * * *",
             rt=dict(
                 sheet="Customers", key_col="customer_id", date_col="job_date", base_status=["active"], stop_cols={"opted_out": "yes", "reviewed": "yes"},
                 steps=[
                     dict(flag="ask1_sent", offset_days=1, window_days=5, marketing=True, subject="How was your {{service}}, {{first_name}}?",
                          body="Hi {{first_name}},\n\nThank you for choosing {{business_name}}. We'd love to hear how it went. If you have a minute, you can leave an honest review here: {{review_link}}\n\nIf anything wasn't right, just reply to this email or call {{business_phone}} and we'll make it right.\n\n{{business_name}}"),
                     dict(flag="ask2_sent", offset_days=10, window_days=14, marketing=True, subject="A quick favor, {{first_name}}",
                          body="Hi {{first_name}},\n\nIf you haven't had a chance yet, an honest review helps small businesses like ours: {{review_link}}\n\nEither way, thank you for your business.\n\n{{business_name}}"),
                 ])),
        dict(id="feedback", kind="intake", title="Private Feedback Form", lite=True, hook="review-feedback",
             rt=dict(
                 sheet="Feedback", id_col="feedback_id", id_prefix="F", dedupe=["email", "rating"],
                 fields=[
                     dict(key="name", required=True, sample="Pat Rivera"),
                     dict(key="email", type="email", required=True, sample="pat@example.test"),
                     dict(key="rating", type="select", required=True, sample="5", options=["1", "2", "3", "4", "5"]),
                     dict(key="comment", max_length=1000, sample="Great job, very thorough."),
                     dict(key="service", max_length=80, sample="House cleaning"),
                 ],
                 extra_cols=[dict(key="priority", value="normal"), dict(key="status", value="new")],
                 tags=[dict(when={"field": "rating", "in": ["1", "2", "3"]}, set=dict(priority="high", status="needs_followup"))],
                 variants=[dict(when={"field": "rating", "in": ["1", "2", "3"]}, ack="low")],
                 ack=dict(subject="Thank you for your feedback, {{first_name}}",
                          body="Hi {{first_name}},\n\nThank you for sharing your feedback. We read every response.\n\nIf you'd like to share your experience publicly, you can do so here: {{review_link}}\n\n{{business_name}}"),
                 acks=dict(low=dict(subject="We're sorry, {{first_name}}. Let us make it right",
                                    body="Hi {{first_name}},\n\nThank you for telling us. We're sorry we fell short, and we'd like to make it right. Someone will contact you personally, or you can call {{business_phone}}.\n\nIf you'd like to share your experience publicly, you can do so here: {{review_link}}\n\n{{business_name}}")),
                 owner=dict(subject="[{{priority}}] {{rating}}-star feedback from {{name}}",
                            body="{{name}} ({{email}}) rated {{service}}: {{rating}}/5.\n\n{{comment}}\n\nIf the rating is 3 or lower, contact them today. Suggested reply to send personally:\n\nHi {{first_name}}, thank you for the honest feedback about your {{service}}. I'm sorry it wasn't what you expected. Can we call you to understand what happened and make it right?\n\nFeedback ID: {{id}}")),
             tests=[dict(name="low rating flagged", set=dict(rating="2"), expect_row=dict(priority="high", status="needs_followup"), expect_variant="low", expect_html=["g.page/r/YOUR-REVIEW-LINK"]),
                    dict(name="high rating normal", set=dict(rating="5"), expect_row=dict(priority="normal"))]),
        dict(id="weekly", kind="digest", title="Weekly Reputation Report", lite=False, cron="0 8 * * 1",
             rt=dict(
                 mode="metrics", window_days=7,
                 sources=[dict(name="customers", sheet="Customers", key_col="customer_id"), dict(name="feedback", sheet="Feedback", key_col="feedback_id")],
                 metrics=[dict(label="Jobs logged", source="customers", op="count", date_col="created_at"),
                          dict(label="Feedback received", source="feedback", op="count", date_col="created_at"),
                          dict(label="Average rating", source="feedback", op="avg", col="rating", date_col="created_at"),
                          dict(label="Low ratings (1-3)", source="feedback", op="count", date_col="created_at", alert_rise_pct=50, where=[{"field": "rating", "in": ["1", "2", "3"]}]),
                          dict(label="Feedback needing follow-up", source="feedback", op="count", where=[dict(field="status", equals="needs_followup")])],
                 subject="Weekly reputation report ({{flagged_count}} alert(s))", intro="Customer feedback for the last {{window_days}} days."),
             test_rows=dict(customers=[dict(customer_id="C1", created_at="2026-10-10")],
                            feedback=[dict(feedback_id="F1", created_at="2026-10-10", rating="2", status="needs_followup"), dict(feedback_id="F2", created_at="2026-10-11", rating="5", status="new")]),
             expect_count=1),
    ],
    listing=dict(title="n8n Local Business Review & Feedback Automation | Review Requests, Private Feedback Form, Low-Rating Alerts",
                 hook="Ask every customer for a review the same way, and hear about unhappy customers the same day."),
    notes=[
        "NO REVIEW GATING. Google, Yelp and Facebook prohibit sending only happy customers to the review site. This pack sends the review link to EVERY customer, and the private feedback form's thank-you also includes the public review link for every rating.",
        "Low ratings alert you so you can follow up personally. The pack never writes or posts replies for you.",
        "Mark `reviewed` = `yes` in the Customers sheet when a customer reviews, to stop reminders. `opted_out` = `yes` after a STOP reply.",
        "Check each platform's current rules about soliciting reviews; they change.",
    ],
    limits=["The pack cannot read your actual reviews from Google/Yelp. The report covers your private feedback form only."],
)
